Ltac qtrans H MU WM :=
  let H' := fresh H in
  pose proof (rw_cells_transport asegs _ _ _ _ _ H MU WM ltac:(cbn [disjoint_from cells_size csize Nat.add Z.of_nat]; lia)) as H';
  clear H; rename H' into H.

