Hypothesis HSP : (bv_unsigned sp <= 2^47)%Z.
Hypothesis HBY : (qbytes gl < 2^56)%Z.
Hypothesis HWG : qwf SB gl.

Definition mW : list (Z * Z) := ((FROM, FROM + 32) :: (TO, TO + 32) :: (bv_unsigned sp - 16, bv_unsigned sp) :: bivs gl)%Z.

